"""Host-only actual fixture method over SQL-handle seams; never rehydrates a live fixture."""
import pathlib,json,subprocess,unittest,shutil,tempfile,os,secrets
ROOT=pathlib.Path(__file__).resolve().parents[2]
PHP=r'''
class Result {public $rows;function __construct($r){$this->rows=$r;}function fetch_assoc(){return $this->rows[0]??null;}function fetch_all($mode){return $this->rows;}}
class State {public $closed=false;public $closeCalls=0;public $mode;function __construct($m){$this->mode=$m;}}
class Statement {public $state;public $sql;public $args;function __construct($s,$q){$this->state=$s;$this->sql=$q;}function bind_param($types,&...$args){$this->args=$args;}function execute(){}function close(){}function get_result(){if(str_contains($this->sql,'events_transactions_current')){if($this->state->mode==='transaction-row-missing'){return new Result(array());}$row=array('global_consumer'=>str_starts_with($this->state->mode,'global-')?($this->state->mode==='global-off'?'NO':null):'YES','thread_consumer'=>str_starts_with($this->state->mode,'thread-')&&$this->state->mode!=='thread-remains'?($this->state->mode==='thread-off'?'NO':null):'YES','instrumented'=>'YES','consumer'=>$this->state->mode==='consumer-off'?'NO':'YES','instrument'=>'YES','active'=>$this->state->mode==='active'?'1':'0');if($this->state->mode==='global-missing'){unset($row['global_consumer']);}if($this->state->mode==='thread-missing'){unset($row['thread_consumer']);}return new Result(array($row));}if($this->args!==array(123,'gov_c_writer_'.str_repeat('a',12))){throw new Exception('unexpected-thread-or-user');}return new Result(array(array('n'=>($this->state->closed&&$this->state->mode!=='thread-remains')?'0':'1')));}}
class Observer {public $state;function __construct($s){$this->state=$s;}function prepare($q){return new Statement($this->state,$q);}function query($q){if(str_contains($q,'fixture_guard')){return new Result(array(array('marker'=>'N07.NATIVE-SOURCE.v1:synthetic-only','quickstart_sha256'=>str_repeat('b',64),'owner_nonce'=>str_repeat('c',64))));}return new Result(array(array('u'=>$this->state->mode==='uuid'?'wrong':'same','t'=>'99','a'=>'1')));}}
class Writer {public $thread_id=123;public $state;function __construct($s){$this->state=$s;}function query($q){return new Result(array(array('principal'=>$this->state->mode==='principal'?'root@localhost':'gov_c_writer_'.str_repeat('a',12).'@%','u'=>'same','t'=>'123','a'=>'1')));}function close(){$this->state->closeCalls++;if($this->state->mode==='close-false'){return false;}$this->state->closed=true;return true;}}
function fixture($mode){$s=new State($mode);$observer=new Observer($s);$f=(new ReflectionClass(PhorgeGovernanceCompletionFixture::class))->newInstanceWithoutConstructor();$values=array('tables'=>array('governance'=>array('fixture_guard'=>true)),'control'=>$observer,'host'=>'127.0.0.1','port'=>3306,'namespace'=>'governance_native_'.str_repeat('a',16),'sourceHash'=>str_repeat('b',64),'ownerNonce'=>str_repeat('c',64),'connections'=>array('setup'=>$observer),'configs'=>array('writer'=>array('host'=>'127.0.0.1','port'=>3306,'namespace'=>'governance_native_'.str_repeat('a',16),'user'=>'gov_c_writer_'.str_repeat('a',12),'password'=>'synthetic')));if($mode!=='missing'){$values['connections']['writer']=new Writer($s);}foreach($values as$k=>$v){(new ReflectionProperty($f,$k))->setValue($f,$v);}return array($f,$s);}
'''
class WriterClose(unittest.TestCase):
 def run_php(self,code):
  full='putenv("PHORGE_GOVERNANCE_ISOLATED_TEST=1");require '+json.dumps(str(ROOT/'support/governance/completion/fixture.php'))+';'+PHP+code
  r=subprocess.run([shutil.which('php'),'-r',full],capture_output=True,timeout=4);self.assertEqual(r.returncode,0,r.stderr);self.assertEqual(r.stderr,b'');return json.loads(r.stdout)
 def test_actual_fixture_closes_exact_independent_writer_unsets_and_keeps_setup(self):
  v=self.run_php('[$f,$s]=fixture("normal");$proof=$f->closeOwnedWriterConnectionForHTTP();$config=$f->getWriterConfig();$f->getAdmin();$connections=(new ReflectionProperty($f,"connections"))->getValue($f);echo json_encode(array("proof"=>$proof,"calls"=>$s->closeCalls,"closed"=>$s->closed,"keys"=>array_keys($connections),"sameUser"=>$config["user"]==="gov_c_writer_".str_repeat("a",12)));');self.assertTrue(v['closed']);self.assertEqual(v['calls'],1);self.assertEqual(v['keys'],['setup']);self.assertTrue(v['sameUser']);self.assertTrue(v['proof']['exact_original_thread_absent']);self.assertEqual(v['proof']['closed_thread_private'],'123');self.assertTrue(v['proof']['all_native_writer_sessions_zero_not_claimed'])
 def test_actual_fixture_wrong_identity_active_tx_and_instrumentation_unknown_refuse_before_close(self):
  for mode in('uuid','principal','active','consumer-off'):
   v=self.run_php('[$f,$s]=fixture('+json.dumps(mode)+');try{$f->closeOwnedWriterConnectionForHTTP();$ok=true;}catch(Throwable$e){$ok=false;}echo json_encode(array("ok"=>$ok,"calls"=>$s->closeCalls,"closed"=>$s->closed));');self.assertFalse(v['ok']);self.assertEqual(v['calls'],0);self.assertFalse(v['closed'])
 def test_actual_fixture_close_failure_and_missing_handle_never_return_proof(self):
  for mode in('close-false','missing'):
   v=self.run_php('[$f,$s]=fixture('+json.dumps(mode)+');try{$f->closeOwnedWriterConnectionForHTTP();$ok=true;}catch(Throwable$e){$ok=false;}echo json_encode(array("ok"=>$ok,"closed"=>$s->closed));');self.assertFalse(v['ok']);self.assertFalse(v['closed'])
 def test_actual_fixture_repeat_refuses_without_reopen_or_second_close(self):
  v=self.run_php('[$f,$s]=fixture("normal");$f->closeOwnedWriterConnectionForHTTP();try{$f->closeOwnedWriterConnectionForHTTP();$refused=false;}catch(Throwable$e){$refused=true;}$f->getWriterConfig();$f->getAdmin();echo json_encode(array("refused"=>$refused,"calls"=>$s->closeCalls,"keys"=>array_keys((new ReflectionProperty($f,"connections"))->getValue($f))));');self.assertTrue(v['refused']);self.assertEqual(v['calls'],1);self.assertEqual(v['keys'],['setup'])
 def test_actual_hold_ready_boundary_never_reached_when_independent_close_fails(self):
  hold=(ROOT/'support/governance/organization/workbench-http-hold.php').read_text();boundary=hold.split('    LiskDAO::closeAllConnections();',1)[1].split('    governance_workbench_http_record($journal,array(\'phase\'=>\'ready\'',1)[0]
  self.assertIn('closeOwnedWriterConnectionForHTTP()',boundary);self.assertLess(boundary.index("cleanup_permitted']=false"),boundary.index('closeOwnedWriterConnectionForHTTP()'))
  for mode in('normal','close-false','global-off','global-null','global-missing','thread-off','thread-null','thread-missing','transaction-row-missing'):
   code='[$fixture,$s]=fixture('+json.dumps(mode)+');$check=static function($value,$name){if($value!==true){throw new Exception("check");}};$journal=array();function governance_workbench_http_record(&$j,$v){$j[]=$v;}try{'+boundary+'$ready=true;}catch(Throwable$e){$ready=false;}echo json_encode(array("ready"=>$ready,"cleanupPermission"=>$GLOBALS["governance_workbench_http_cleanup_permitted"],"journal"=>$journal));'
   v=self.run_php(code);self.assertEqual(v['ready'],mode=='normal');self.assertFalse(v['cleanupPermission']);self.assertEqual(len(v['journal']),1 if mode=='normal'else 0)

 def test_closed_handle_but_independent_thread_not_absent_refuses_without_reopening(self):
  v=self.run_php('[$f,$s]=fixture("thread-remains");try{$f->closeOwnedWriterConnectionForHTTP();$ok=true;}catch(Throwable$e){$ok=false;}echo json_encode(array("ok"=>$ok,"closed"=>$s->closed,"calls"=>$s->closeCalls,"keys"=>array_keys((new ReflectionProperty($f,"connections"))->getValue($f))));');self.assertFalse(v['ok']);self.assertTrue(v['closed']);self.assertEqual(v['calls'],1);self.assertEqual(v['keys'],['setup'])

 def test_actual_fixture_upstream_global_thread_consumer_NO_NULL_missing_refuse_before_close(self):
  for mode in('global-off','global-null','global-missing','thread-off','thread-null','thread-missing','transaction-row-missing'):
   v=self.run_php('[$f,$s]=fixture('+json.dumps(mode)+');try{$f->closeOwnedWriterConnectionForHTTP();$ok=true;}catch(Throwable$e){$ok=false;}echo json_encode(array("ok"=>$ok,"calls"=>$s->closeCalls,"closed"=>$s->closed));');self.assertFalse(v['ok']);self.assertEqual(v['calls'],0);self.assertFalse(v['closed'])
